function safeParseLocal(raw,fallback){try{const p=JSON.parse(raw);if(p&&p.__precisionEnvelope){if(p.expiresAt&&Date.now()>p.expiresAt)return fallback;return p.data??fallback}return p}catch{return fallback}}
