window.__precisionAppLoaded=true;
const LS=(()=>{try{const s=window.localStorage;const t='__precision_storage_probe__';s.setItem(t,'1');s.removeItem(t);return s}catch{return {getItem:k=>__precisionMemoryStorage.has(k)?__precisionMemoryStorage.get(k):null,setItem:(k,v)=>__precisionMemoryStorage.set(k,String(v)),removeItem:k=>__precisionMemoryStorage.delete(k),clear:()=>__precisionMemoryStorage.clear(),key:i=>Array.from(__precisionMemoryStorage.keys())[i]||null,get length(){return __precisionMemoryStorage.size}}}})();
