const esc=s=>String(s??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m]));
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(quoted){if(c==='\"'&&n==='\"'){cell+='\"';i++;}else if(c==='\"'){quoted=false}else cell+=c}else{if(c==='\"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell);rows.push(row);row=[];cell=''}else if(c==='\r'){}else cell+=c}}if(cell.length||row.length){row.push(cell);rows.push(row)}if(!rows.length)return[];const headers=rows.shift().map(h=>h.trim());return rows.filter(r=>r.some(v=>v!=='')).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])))}
async function loadText(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(url+' '+r.status);return r.text()}
async function loadJSON(url){return JSON.parse(await loadText(url))}
async function loadAll(){
 const m=await loadJSON('./data/PORTAL_DATA_MANIFEST_PHASE_B.json');state.manifest=m;
 const pairs=await Promise.all([
  loadText('./data/core/pyq_master_integrated_2014_2026.csv'),loadText('./data/pyq_1300_master_v4.csv'),loadText('./data/analysis/year_analysis_2014_2026.csv'),loadText('./data/research/post_2026_mock_ecosystem.csv'),loadText('./data/research/post_2026_public_quiz_stream.csv'),loadText('./data/core/source_registry_baseline.csv'),loadText('./data/research/post_2026_research_registry.csv'),loadText('./data/core/qa_gates_baseline.csv'),loadText('./data/core/answer_qa_baseline.csv'),loadJSON('./data/analysis/phase_a_integrity.json'),loadJSON('./data/analysis/qa_summary_phase_a.json'),loadJSON('./data/search_index.json')
 ]);
 const integrated=parseCSV(pairs[0]);
 const fullMaster=parseCSV(pairs[1]);
 const fullById=new Map(fullMaster.map(r=>[r.id,r]));
 state.pyq=integrated.map(r=>{const f=fullById.get(r.id)||{};return {...r,question_text:f.question_text||r.question_text||'',question_text_excerpt:f.question_text_excerpt||r.question_text_excerpt||'',text_quality:f.text_quality||r.text_quality||'',subject:r.subject||f.subject||'',subtopic:r.subtopic||f.subtopic||''};});
 state.year=parseCSV(pairs[2]);state.mocks=parseCSV(pairs[3]);state.quizzes=parseCSV(pairs[4]);state.sources=[...parseCSV(pairs[5]).map(x=>({...x,tier:'Baseline'})),...parseCSV(pairs[6])];state.gates=parseCSV(pairs[7]);state.answerQA=parseCSV(pairs[8]);state.findings={integrity:pairs[9],qa_summary:pairs[10]};state.searchIndex=pairs[11];state.features=parseCSV(await loadText('./data/feature_registry_v7.csv').catch(()=>loadText('./data/feature_registry_v5.csv').catch(()=>loadText('./data/feature_registry_v4.csv'))));
}
function metric(label,val,sub,cls='cyan'){return `<div class="card metric"><div class="label">${esc(label)}</div><div class="value ${cls}">${esc(val)}</div><div class="delta">${esc(sub)}</div></div>`}
function bar(label,val,max=100,suffix=''){const pct=Math.max(0,Math.min(100,(Number(val)||0)/max*100));return `<div class="barrow"><span>${esc(label)}</span><div class="bar"><div class="fill" style="width:${pct}%"></div></div><b>${esc(val)}${suffix}</b></div>`}
function badge(x){return `<span class="tag">${esc(x)}</span>`}
function fileHref(path){return path?.startsWith('../')?path.slice(3):'./data/'+path}
function weakAreas(){
 const recent=state.year.filter(r=>Number(r.year)>=2023);
 const subjects=['Economy','Environment & Ecology','Geography','History','Polity & Governance','Science & Technology','Art & Culture','International Relations'];
 const scores=subjects.map(s=>{const recentAvg=recent.length?recent.reduce((a,r)=>a+(Number(r[s])||0),0)/recent.length:0;const allAvg=state.year.length?state.year.reduce((a,r)=>a+(Number(r[s])||0),0)/state.year.length:0;return {s,recentAvg,allAvg,delta:recentAvg-allAvg}});
 const verification=state.pyq.filter(r=>r.primary_source_status==='PRIMARY_VERIFIED').length/state.pyq.length*100;
 return [
  {title:'Primary-source verification coverage',value:`${verification.toFixed(1)}%`,detail:'Evidence gate remains the largest data-quality bottleneck.',type:'DATA QUALITY'},
  {title:'2026 full question-text coverage',value:'LIMITED',detail:'Official 2026 paper remains source-of-record; current portal layer uses public topic/title inventory rather than inferred stems.',type:'DATA QUALITY'},
  {title:'Answer-key reconciliation',value:String(state.answerQA.length),detail:'Flagged answer records require authoritative-key reconciliation before release.',type:'QA'},
  {title:'Recent subject rotation',value:scores.sort((a,b)=>a.delta-b.delta)[0]?.s||'—',detail:'This is a coverage-change signal, not a prediction; inspect Trend Analytics for the full matrix.',type:'STRUCTURAL'}
 ];
}
function viewOverview(){
 const total=state.pyq.length||1000,verified=state.pyq.filter(r=>r.primary_source_status==='PRIMARY_VERIFIED').length,blocked=total-verified,weak=weakAreas();
 return `<div class="view-head"><div><div class="eyebrow">COMMAND CENTER / TRAINING STATE</div><div class="title">${esc(state.ui.title||"Precision Training Control Room")}</div><div class="desc">${esc(state.ui.note||"Personal-use research cockpit.")} Historical PYQs, the official 2026 style anchor, post-2026 public mock intelligence and QA evidence are kept in separate layers.</div></div><div>${badge('PERSONAL USE')} ${badge('DATA LINKED')}</div></div>
 <div class="grid g4">${metric('PYQ RECORDS',total,'2014–2026 frozen corpus','cyan')}${metric('PRIMARY VERIFIED',verified,'strict evidence gate','green')}${metric('QA / BLOCKED',blocked,'not release-ready','amber')}${metric('RESEARCH SOURCES',state.sources.length,'registry + post-2026 public layer','purple')}</div>
 <div class="grid g2" style="margin-top:14px"><div class="card"><div class="split"><h3 class="section-title">Weak areas / bottlenecks</h3>${badge('ACTIONABLE')}</div>${weak.map(x=>`<div class="notice weak-card"><div class="split"><strong>${esc(x.title)}</strong>${badge(x.type)}</div><div class="weak-value">${esc(x.value)}</div><div>${esc(x.detail)}</div></div>`).join('')}</div>
 <div class="card"><div class="split"><h3 class="section-title">Training doctrine</h3>${badge('V7 FINAL')}</div><div class="nodegrid">${['Historical PYQs → structural priors','Official 2026 paper → latest style anchor','Post-2026 mocks/quizzes → ecosystem signal','Primary source → evidence gate','Answer + bilingual QA → release gate','Similarity control → no PYQ paraphrase'].map((x,i)=>`<div class="node"><b>${String(i+1).padStart(2,'0')}</b><small>${esc(x)}</small></div>`).join('')}</div><div class="notice" style="margin-top:12px"><strong>Mock engine:</strong> architecture active; question generation remains a separate controlled release gate.</div></div></div>${state.admin?`<div class="card admin-editor" style="margin-top:14px"><div class="split"><h3 class="section-title">In-page Admin Editor</h3>${badge('LOCAL ONLY')}</div><div class="grid g2"><div><label class="small muted">Dashboard title</label><input id="adminTitle" class="ai-input single" value="${esc(state.ui.title||'PRECISION')}"></div><div><label class="small muted">Dashboard note</label><input id="adminNote" class="ai-input single" value="${esc(state.ui.note||'Personal UPSC CSE Prelims 2027 GS-I research cockpit.')}"></div></div><div class="actions" style="margin-top:10px"><button class="btn primary" id="saveAdminEdit">Save page edits</button><button class="btn" id="resetAdminEdit">Reset</button></div></div>`:''}`;
}
function pyqTopic(r){return String(r.topic||r.Topic||r.subtopic||r.micro_topic||'Unclassified').trim()||'Unclassified'}
function pyqTheme(r){const x=String(r.theme||r.Theme||r.theme_name||r.raw_subject||r.subject||'Unclassified').trim();return x||'Unclassified'}
function getFiltered(){const f=state.filters||{};return state.pyq.filter(r=>{
 const y=f.year==='ALL'||r.year===f.year,s=f.subject==='ALL'||r.subject===f.subject,th=f.theme==='ALL'||pyqTheme(r)===f.theme,tp=f.topic==='ALL'||pyqTopic(r)===f.topic,fo=f.format==='ALL'||String(r.format||'')===f.format;
 const st=f.status==='ALL'||(f.status==='VERIFIED'?r.primary_source_status==='PRIMARY_VERIFIED':r.primary_source_status!=='PRIMARY_VERIFIED');
 const ca=f.ca==='ALL'||(f.ca==='YES'?String(r.explicit_current_affairs_tag).toLowerCase()==='true':String(r.explicit_current_affairs_tag).toLowerCase()!=='true');
 const neg=f.neg==='ALL'||(f.neg==='YES'?String(r.negative_stem).toLowerCase()==='true':String(r.negative_stem).toLowerCase()!=='true');
 const news=f.news==='ALL'||(f.news==='YES'?String(r.news_cue).toLowerCase()==='true':String(r.news_cue).toLowerCase()!=='true');
 const hay=[r.id,r.year,r.qnum,r.raw_subject,r.subject,pyqTheme(r),pyqTopic(r),r.format,r.primary_source,r.primary_source_organization,r.question_text_source,r.secondary_source_claim].join(' ').toLowerCase();
 return y&&s&&th&&tp&&fo&&st&&ca&&neg&&news&&(!f.q||hay.includes(String(f.q).toLowerCase()));});}
