 const groups={'CORE DATA':['data/core/pyq_master_integrated_2014_2026.csv','data/core/source_tracking_2014_2026.csv','data/core/source_registry_baseline.csv','data/core/answer_qa_baseline.csv','data/core/qa_gates_baseline.csv'],'ANALYSIS':['data/analysis/year_analysis_2014_2026.csv','data/analysis/subject_by_year_2014_2026.csv','data/analysis/format_analysis_2014_2026.csv','data/analysis/ca_signal_by_year_2014_2026.csv','data/analysis/subtopic_recurrence_2014_2026.csv','data/analysis/pyq_analysis_package_2014_2026/'],'RESEARCH':['data/research/post_2026_mock_ecosystem.csv','data/research/post_2026_public_quiz_stream.csv','data/research/post_2026_research_registry.csv','data/research/external_2026_calibration.csv','data/research/POST_2026_PRELIMS_MOCK_INTELLIGENCE_2026_27_v1.csv'],'COACHING':['data/coaching/coaching_schedule_allocation_2026_2027.csv','data/coaching/coaching_schedule_analysis_2026_2027.md','data/coaching/coaching_mock_analysis_overview_2026_2027.md'],'CONTROL / ARCHIVE':['data/PORTAL_DATA_MANIFEST_PHASE_B.json','database/precision_upsc_phase_b.sqlite','archives/phase_a_input_workbook_provenance.xlsx','archives/precision_training_state_2017_2026_source.xlsx']};
