function applyUI(){if(state.ui.title){document.title=state.ui.title;const t=document.querySelector('.brandname');if(t)t.textContent=state.ui.title||'PRECISION'}}
function adminPanel(){if(!state.admin)return '';return `<div class="admin-ribbon"><strong>ADMIN EDIT MODE</strong><span>Local-only</span><button id="adminExit" class="ghost">Exit</button><button id="adminReset" class="ghost">Reset UI edits</button></div>`}
function parsePYQQuestionText(text){const raw=String(text||'').trim();if(!raw)return {stem:'',options:[]};const patterns=[/\(\s*([abcd])\s*\)\s*/ig,/\b([ABCD])\)\s+/g];let best=[];for(const re of patterns){const hits=[...raw.matchAll(re)];if(hits.length>best.length)best=hits}if(!best.length)return {stem:raw,options:[]};const stem=raw.slice(0,best[0].index).trim();const options=best.map((h,i)=>({letter:h[1].toUpperCase(),text:raw.slice(h.index+h[0].length,i+1<best.length?best[i+1].index:raw.length).trim()}));return {stem,options}}
function showDetail(id){if(id==='__ANSWER_KEY__'){const t=selectedTest(),k=evalState().answerKeys[t.testNo]||{},box=document.createElement('div');box.className='modal';box.innerHTML=`<div class="modal-bg"></div><div class="modal-card"><button class="close" id="close">×</button><div class="eyebrow">ANSWER KEY VAULT</div><h2>Mock ${String(t.testNo).padStart(2,'0')} • ${esc(t.paperCode)}</h2><pre class="key-preview">${esc(answerKeyRows(t.testNo))}</pre></div>`;document.body.appendChild(box);box.querySelector('#close').onclick=()=>box.remove();box.querySelector('.modal-bg').onclick=()=>box.remove();return}
 const r=state.pyq.find(x=>x.id===id);if(!r)return;const parsed=parsePYQQuestionText(r.question_text||r.question_text_excerpt);const is2026=Number(r.year)===2026&&String(r.text_quality||'').toUpperCase().includes('TOPIC_TITLE_ONLY');const box=document.createElement('div');box.className='modal';box.innerHTML=`<div class="modal-bg"></div><div class="modal-card pyq-detail-modal"><button class="close" id="close">×</button><div class="eyebrow">${esc(r.id)} • ${esc(r.year)}</div><h2>${esc(r.subject)} • ${esc(r.subtopic)}</h2>${is2026?`<div class="notice"><strong>2026 source-of-record mode:</strong> this local row is a title/topic inventory. The full official 2026 General Studies Paper-I is available directly from UPSC here. <a class="link linkbtn" href="${esc(r.official_paper_source_url||'https://www.upsc.gov.in/examinations/Civil%20Services%20%28Preliminary%29%20Examination%2C%202026')}" target="_blank" rel="noopener">Open official 2026 paper ↗</a></div>`:`<div class="question-stem">${esc(parsed.stem||r.question_text||'')}</div>${parsed.options.length?`<div class="pyq-options">${parsed.options.map(o=>`<div class="pyq-option"><b>(${o.letter})</b><span>${esc(o.text)}</span></div>`).join('')}</div>`:''}`}<div class="grid g2" style="margin-top:14px"><div class="notice"><strong>Format</strong><br>${esc(r.format)} • ${esc(r.statement_count)} statements • ${esc(r.stem_word_count)} words • ${esc(r.option_count||parsed.options.length)} options</div><div class="notice"><strong>Source status</strong><br>${esc(r.primary_source_status||'UNVERIFIED')}<br>${r.primary_source_url?`<a class="link" href="${esc(r.primary_source_url)}" target="_blank" rel="noopener">${esc(r.primary_source||'Primary source')} ↗</a>`:`<a class="link" href="${esc(r.official_paper_source_url||'https://www.upsc.gov.in/examinations/previous-question-papers')}" target="_blank" rel="noopener">Official UPSC archive ↗</a>`}</div></div></div>`;document.body.appendChild(box);box.querySelector('#close').onclick=()=>box.remove();box.querySelector('.modal-bg').onclick=()=>box.remove()}

function activityState(){return loadLocalJSON('precision-study-activity',{days:{},events:[],current:{startedAt:Date.now(),lastAt:Date.now()},version:1})}
function saveActivity(a){saveLocalJSON('precision-study-activity',a)}
function todayKey(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})}

