function showLockError(msg){const e=document.getElementById('deviceLockError');if(e){e.textContent=msg;e.hidden=!msg}}
function bytesToB64(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function randomSalt(){const b=new Uint8Array(16);crypto.getRandomValues(b);return bytesToB64(b)}
function b64ToBytes(s){const x=String(s||'').replace(/-/g,'+').replace(/_/g,'/');const p=x+'='.repeat((4-x.length%4)%4);const bin=atob(p);return Uint8Array.from(bin,c=>c.charCodeAt(0))}
async function passwordHash(password,salt,iterations=120000){const enc=new TextEncoder();const baseKey=await crypto.subtle.importKey('raw',enc.encode(String(password)),{name:'PBKDF2'},false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:b64ToBytes(salt),iterations,hash:'SHA-256'},baseKey,256);return bytesToB64(new Uint8Array(bits))}
async function setPortalPassword(password){const p=String(password||'');if(p.length<8)return{ok:false,msg:'Use a password of at least 8 characters.'};const salt=randomSalt(),iterations=120000,hash=await passwordHash(p,salt,iterations);saveDeviceLock({enabled:true,salt,hash,iterations,createdAt:Date.now(),updatedAt:Date.now()});return{ok:true,msg:'Portal password created. PRECISION is unlocked.'}}
async function verifyPortalPassword(password){const saved=deviceLockState();if(!saved.enabled||!saved.salt||!saved.hash)return{ok:true,msg:'No password is configured.'};try{const hash=await passwordHash(String(password||''),saved.salt,Number(saved.iterations)||120000);if(hash!==saved.hash)return{ok:false,msg:'Incorrect portal password.'};unlockPortalUI();return{ok:true,msg:'Portal unlocked.'}}catch(e){return{ok:false,msg:'Password verification failed. Please retry.'}}}
async function authenticateDeviceLock(){const p=document.getElementById('portalPassword')?.value||'';return verifyPortalPassword(p)}
function installDeviceLockUI(){if(!document?.getElementById||!document?.createElement||!document?.body)return;if(document.getElementById('deviceLockOverlay'))return;const o=document.createElement('div');o.id='deviceLockOverlay';o.hidden=true;o.innerHTML='<div class="device-lock-card"><div class="lockicon">🔐</div><div class="eyebrow">PORTAL PASSWORD</div><h2>PRECISION is locked</h2><p>Enter your private portal password to continue. The password is never sent to the server.</p><input id="portalPassword" type="password" autocomplete="current-password" class="ai-input single" placeholder="Enter portal password" style="margin:12px 0"><input id="portalPasswordConfirm" type="password" autocomplete="new-password" class="ai-input single" placeholder="Confirm password" style="margin:0 0 10px;display:none"><button class="btn primary" id="unlockDeviceBtn">Unlock PRECISION</button><div id="deviceLockError" class="notice error" hidden style="margin-top:10px"></div></div>';document.body.appendChild(o);const p=o.querySelector('#portalPassword');p?.addEventListener('keydown',e=>{if(e.key==='Enter')o.querySelector('#unlockDeviceBtn')?.click()});if(deviceLockState().enabled)setTimeout(lockPortal,0)}


