function installHInteractions(){
  if(window.__precisionInteractionsInstalled)return;
  window.__precisionInteractionsInstalled=true;
  window.addEventListener('error',e=>{try{const msg=e?.error?.message||e?.message||'Unexpected interface error';const bar=document.getElementById('runtimeErrorBar');if(bar){bar.hidden=false;bar.textContent='Interface recovered: '+msg+' • Retry the current view if needed.';}console.error('PRECISION runtime error',e.error||e.message||e);}catch{}});
  window.addEventListener('unhandledrejection',e=>{try{const msg=e?.reason?.message||String(e?.reason||'Promise error');const bar=document.getElementById('runtimeErrorBar');if(bar){bar.hidden=false;bar.textContent='Background action recovered: '+msg;}console.error('PRECISION rejection',e.reason);}catch{}});
  document.addEventListener('keydown',e=>{const tag=(e.target?.tagName||'').toLowerCase();const editing=['input','textarea','select'].includes(tag)||e.target?.isContentEditable;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();const a=document.getElementById('aiPrompt')||document.getElementById('aiPrompt_G');if(a){a.focus();a.select?.()}else setView('ai')}if(!editing&&e.code==='Space'&&state.view==='study'){const st=studyState();if(st.active){e.preventDefault();if(st.active.pausedAt)resumeStudySession();else pauseStudySession('keyboard');render()}}if(!editing&&e.key.toLowerCase()==='f'&&state.view==='study'){document.getElementById('focusStudyMode')?.click()}if(e.key==='Escape')document.querySelectorAll('.modal').forEach(m=>m.remove())});
  try{Promise.resolve(navigator.storage?.persist?.()).catch(()=>{});}catch{}
}
function updateNetworkState(){const online=navigator.onLine!==false;const els=['#networkState','#topNetwork'];const msg=online?'ONLINE • LOCAL CACHE READY':'OFFLINE • LOCAL CACHE READY';for(const sel of els){const el=$(sel);if(!el)continue;if(sel==='#topNetwork'){el.textContent=online?'TRAINING / RESEARCH MODE • AI + DATA LINKED':'OFFLINE • LOCAL DATA MODE'}else el.textContent=msg}document.documentElement.dataset.network=online?'online':'offline'}
function runtimeErrorBarHTML(){return '<div id="runtimeErrorBar" class="runtime-error-bar" hidden></div>'}

async function render(){
 const main=$('#main');if(!main)return;
 if(!state.pyq.length&&!window.__PRECISION_V8_ACTIVE){main.innerHTML='<div class="loading"><div class="spinner"></div><div>Loading linked training data…</div></div>';try{await loadAll()}catch(e){main.innerHTML=`<div class="card locked"><div><h2>Data load error</h2><p class="desc">${esc(e.message)}. The shell remains available; retry after restoring the data files/network cache.</p><div class="actions" style="justify-content:center;margin-top:12px"><button class="btn primary" id="retryData">Retry data load</button></div></div></div>`;$('#retryData')?.addEventListener('click',()=>{state.pyq=[];render()});return}}
 let rendered=runtimeErrorBarHTML();
 try{rendered=(state.engine?.run&&['COUNTDOWN','RUNNING','PAUSED','SUBMIT_READY'].includes(state.engine.run.state)?'<div class="recovery-banner">● Active test session recovered locally • '+esc(state.engine.run.paperCode||'paper')+' • '+esc(state.engine.run.state)+' • autosave active</div>':'')+adminPanel()+(views[state.view]||viewOverview)()}catch(e){console.error('PRECISION render view error',e);rendered=`<div class="card locked"><div><div class="lockicon">△</div><h2>Module recovered from an error</h2><p class="desc">${esc(e.message||e)}. Navigation remains available. Use Retry View to reload this module.</p><div class="actions" style="justify-content:center;margin-top:12px"><button class="btn primary" id="retryView">Retry View</button><button class="btn" id="homeRecovery">Open Overview</button></div></div></div>`}
 main.innerHTML=rendered;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
 try{applyUI()}catch(e){console.error('applyUI error',e)}
 try{bind()}catch(e){console.error('bind error',e);main.insertAdjacentHTML('afterbegin',`<div class="notice error" style="margin-bottom:12px"><strong>Interaction recovery:</strong> ${esc(e.message||e)}</div>`)}
 try{updateNetworkState()}catch(e){}
 $('#retryView')?.addEventListener('click',()=>render());$('#homeRecovery')?.addEventListener('click',()=>setView('overview'));
 try{activityPing()}catch{}
}
setInterval(()=>{const e=engineState();if(e.run&&(e.run.state==='COUNTDOWN'||e.run.state==='RUNNING')){tickTimer();const c=$('#engineClock');if(c){const r=e.run;c.textContent=r.state==='COUNTDOWN'?fmtTime(r.countdownRemaining):fmtTime(Math.max(0,7200-(r.elapsed||0)));}const u=$('#unlockClock');if(u){const q=evalState().queue.filter(x=>x.testNo===selectedTest().testNo).slice(-1)[0];if(q)u.textContent=fmtTime(Math.ceil(Math.max(0,q.unlockAt-Date.now())/1000));}}},1000);


