function gDBSummary(prompt='',deep=false){
  const subjects={}; for(const r of state.pyq){subjects[r.subject]=(subjects[r.subject]||0)+1}
  const years={}; for(const r of state.pyq){years[r.year]=(years[r.year]||0)+1}
  const fmts={}; for(const r of state.pyq){fmts[r.format]=(fmts[r.format]||0)+1}
  const ca=state.pyq.filter(r=>String(r.explicit_current_affairs_tag).toLowerCase()==='true'||String(r.news_cue).trim()).length;
  const verified=state.pyq.filter(r=>r.primary_source_status==='PRIMARY_VERIFIED').length;
  const searchHit=gRankedPYQ(prompt,deep?60:24);
  const compact=searchHit.map(r=>({id:r.id,year:r.year,subject:r.subject,subtopic:r.subtopic,format:r.format,statements:r.statement_count,negative:r.negative_stem,ca:r.explicit_current_affairs_tag,newsCue:r.news_cue,sourceStatus:r.primary_source_status,source:r.primary_source}));
  const st=studyState(); const subjectTotals=Object.fromEntries(STUDY_SUBJECTS.map(m=>[m.label,Number(st.subjects[m.label]||0)])); return {scope:'PRECISION UPSC CSE Prelims 2027 GS-I personal research portal',pyq_records:state.pyq.length,verified_primary_source_records:verified,source_coverage_percent:state.pyq.length?(verified/state.pyq.length*100).toFixed(1):'0.0',years,subjects,formats:fmts,ca_or_news_cue_records:ca,qa_flags:state.answerQA.length,gate_records:state.gates.length,mock_intelligence_records:state.mocks.length,research_source_records:state.sources.length,relevant_pyq_records:compact,training_unlock:gPrefs().trainingUnlocked!==false,scoring:'Correct +2 / Wrong -1/3 / Blank 0',test_architecture:'50 tests × 100 questions; paper code + D-Day engine',study_subjects:STUDY_SUBJECTS.map(m=>({id:m.id,label:m.label,group:m.group})),study_subject_totals_seconds:subjectTotals,study_active:st.active?{subject:st.active.subject,elapsed_seconds:studyElapsedSec(st.active)}:null,ai_capabilities_count:AI_CAPABILITIES.length,ai_capabilities:AI_CAPABILITIES,source_rule:'PYQ year Y accepts original/primary source date <= Y; later documents are retrospective corroboration only',deep_context:deep};
}
