function gSystemPrompt(mode,prompt,deep=false){
  const cfg=gConfig();
  const summary=gDBSummary(prompt,deep);
  const actions=['navigate','rename','note','hideSignals','showSignals','togglePanel','addModule','removeModule','setCountdown','openTraining','resetUI','openPYQ','openStudyTimer','openOMR','saveStudyGoal'];
  return `You are PRECISION AI, the controlled AI operator and research analyst for a personal UPSC CSE Prelims 2027 GS-I dashboard.

MODE: ${mode}
USER COMMAND: ${prompt}

PORTAL MODULE MAP (every view in this portal, A to Z — you must know all of these and may reference/navigate to any of them):
${gPortalModuleMap()}

CONVERSATION MEMORY (this device's recent AI turns — saved permanently in local storage, survives refresh/close; use it for continuity, do not repeat yourself, build on prior answers):
${gConversationMemory()}

DATABASE CONTEXT (authoritative local portal snapshot):
${JSON.stringify(summary)}

CORE RULES:
1) Treat local database values as authoritative for portal facts; never invent missing rows or answer keys.
2) For research/current facts, clearly distinguish local database evidence, web-grounded evidence, inference, and uncertainty.
3) Respect the source rule: for PYQ year Y, accepted original/primary source date must be <= Y; later documents are retrospective corroboration, never the original-source field.
4) The scoring rule is +2 correct, -1/3 wrong, 0 blank.
5) This is a private personal-use portal.
6) Never delete historical data; UI edits must be reversible and logged.
7) The portal has ${AI_CAPABILITIES.length} registered AI capabilities. Use the feature catalog and the portal module map above as the capability map, but never claim an unsupported backend action exists.
8) You have full A-to-Z knowledge of every module above — when the student asks "what can this portal do" or similar, answer from the module map, not a partial list.
9) Treat CONVERSATION MEMORY as real memory of this student across sessions — refer back to earlier topics naturally when relevant.

CONTROLLED UI ACTIONS (only these may be executed automatically): ${actions.join(', ')}.
For COMMAND mode return ONLY JSON: {"reply":"brief confirmation","actions":[{"action":"navigate|rename|note|hideSignals|showSignals|togglePanel|addModule|removeModule|setCountdown|openTraining|resetUI|openPYQ|openStudyTimer|openOMR|saveStudyGoal","value":"...","module":{},"panel":"...","enabled":true}]}
Allowed addModule kinds: note, metric, checklist, link, countdown. No source-code execution, no arbitrary JS, no destructive data deletion.

FEATURE CATALOG (synced registry):
${AI_CAPABILITIES.map((x,i)=>`${i+1}. ${x}`).join('\n')}

For ANALYST mode, return a professional database-oriented answer with concise headings, evidence labels, relevant PYQ IDs where available, and explicit uncertainty.
Current configured model: ${cfg.model}.`;
}
const DEFAULT_PUBLIC_GEMINI_KEY='';
function gModel(){return LS.getItem('precision-ai-model')||gConfig().model}
function gBase(){return LS.getItem('precision-ai-base')||gConfig().base}
function gKey(){const saved=LS.getItem('precision-ai-key');if(saved)return saved;try{LS.setItem('precision-ai-key',DEFAULT_PUBLIC_GEMINI_KEY)}catch{}return DEFAULT_PUBLIC_GEMINI_KEY}
function geminiURL(stream=false){const base=gBase().replace(/\/$/,'');const model=encodeURIComponent(gModel());return `${base}/models/${model}:${stream?'streamGenerateContent?alt=sse':'generateContent'}`}
function showAIStatus(msg,kind='info'){const el=$('#aiStatus');if(el){el.className='notice '+(kind==='error'?'error':'');el.textContent=msg}}
function gTextFromResponse(data){
  const parts=[];
  for(const c of (data?.candidates||[])){for(const p of (c?.content?.parts||[])){if(p?.text)parts.push(p.text)}}
  return parts.join('');
}
function gGroundingSources(data){
  const chunks=data?.groundingMetadata?.groundingChunks||[];
  return chunks.filter(x=>x?.web?.uri).map(x=>({title:x.web.title||x.web.uri,url:x.web.uri})).slice(0,12);
}
async function geminiGenerate(prompt,{command=false,web=false,deep=false}={}){
 const key=gKey();if(!key)throw new Error('Gemini API key is not configured.');
 const headers={'Content-Type':'application/json','x-goog-api-key':key};
 const body={contents:[{role:'user',parts:[{text:gSystemPrompt(command?'COMMAND':'ANALYST',prompt,deep)}]}],generationConfig:{maxOutputTokens:command?2200:7000,thinkingConfig:{thinkingLevel:deep?'high':'medium'}}};
 if(command)body.generationConfig.responseMimeType='application/json';
 if(web)body.tools=[{google_search:{}}];
 const url=geminiURL(false);const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),45000);
 try{const r=await fetch(url,{method:'POST',headers,body:JSON.stringify(body),signal:ctl.signal});if(!r.ok){let msg='Gemini API '+r.status;try{const j=await r.json();msg=j?.error?.message||msg}catch{};throw new Error(msg)}const data=await r.json();return {text:gTextFromResponse(data),sources:gGroundingSources(data),queries:data?.groundingMetadata?.webSearchQueries||[]};}finally{clearTimeout(timer)}
}
async function geminiStream(prompt,opts={}){const key=gKey();if(!key)throw new Error('Gemini API key is not configured.');const headers={'Content-Type':'application/json','x-goog-api-key':key};const body={contents:[{role:'user',parts:[{text:gSystemPrompt('ANALYST',prompt,!!opts.deep)}]}],generationConfig:{maxOutputTokens:7000,thinkingConfig:{thinkingLevel:opts.deep?'high':'medium'}}};if(opts.web)body.tools=[{google_search:{}}];const url=geminiURL(true),ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),60000);try{const r=await fetch(url,{method:'POST',headers,body:JSON.stringify(body),signal:ctl.signal});if(!r.ok){let msg='Gemini stream '+r.status;try{const j=await r.json();msg=j?.error?.message||msg}catch{}throw new Error(msg)}if(!r.body)return geminiGenerate(prompt,opts);const reader=r.body.getReader(),decoder=new TextDecoder();let buf='',full='';const sources=[],queries=[];while(true){const {value,done}=await reader.read();if(done)break;buf+=decoder.decode(value,{stream:true});const lines=buf.split(/\r?\n/);buf=lines.pop()||'';for(const line of lines){const t=line.replace(/^data:\s*/,'').trim();if(!t||t==='[DONE]')continue;try{const j=JSON.parse(t),chunk=gTextFromResponse(j);if(chunk){full+=chunk;opts.onText?.(full)}sources.push(...gGroundingSources(j));queries.push(...(j?.groundingMetadata?.webSearchQueries||[]))}catch{}}}return {text:full,sources:[...new Map(sources.map(x=>[x.url,x])).values()].slice(0,12),queries:[...new Set(queries)]};}finally{clearTimeout(timer)}}
function gParseJSON(text){try{return JSON.parse(String(text).replace(/^```json\s*/,'').replace(/```$/,'').trim())}catch{const m=String(text).match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0])}catch{}}return null}}
function gRunActions(payload){
  const actions=Array.isArray(payload?.actions)?payload.actions:payload?.action?[payload]:[];let applied=0,notes=[];
  for(const item of actions){const a=item.action,value=item.value??'';
    if(a==='navigate'){const v=gNavigate(value);if(v){notes.push('Opened '+v);applied++;}continue}
    if(a==='rename'){applyUIWithVersion('AI rename',ui=>{ui.title=String(value).slice(0,120)});applied++;continue}
    if(a==='note'){applyUIWithVersion('AI note',ui=>{ui.note=String(value).slice(0,1000)});applied++;continue}
    if(a==='hideSignals'||a==='showSignals'){applyUIWithVersion('AI signal visibility',ui=>{ui.hideSignals=a==='hideSignals'});applied++;continue}
    if(a==='togglePanel'){const panel=String(item.panel||value).trim();const enabled=item.enabled!==false;applyUIWithVersion('AI panel toggle',ui=>{ui.panels=ui.panels||{};ui.panels[panel]=enabled});applied++;continue}
    if(a==='addModule'){const mod=item.module&&typeof item.module==='object'?item.module:{title:value,kind:'note',content:value};mod.id=mod.id||'ai-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);mod.title=String(mod.title||'AI Module').slice(0,100);mod.kind=['note','metric','checklist','link','countdown'].includes(mod.kind)?mod.kind:'note';mod.content=String(mod.content??value).slice(0,2000);mod.at=new Date().toISOString();const before=JSON.parse(JSON.stringify(state.ui));saveModules([...gModules(),mod]);recordVersion('AI add module',before,state.ui);applied++;notes.push('Added module '+mod.title);continue}
    if(a==='removeModule'){const id=String(value);const before=JSON.parse(JSON.stringify(state.ui));saveModules(gModules().filter(m=>m.id!==id&&m.title!==id));recordVersion('AI remove module',before,state.ui);applied++;continue}
    if(a==='setCountdown'){const id=String(item.panel||item.value||'');const date=String(item.module?.date||item.value||'');const cfg=gConfig();const found=cfg.events.find(e=>e.id===id||e.name.toLowerCase().includes(id.toLowerCase()));if(found&&date){found.date=date;saveGConfig(cfg);applied++;notes.push('Updated '+found.name)}continue}
    if(a==='openTraining'){setView('training');saveGPrefs({trainingUnlocked:true});applied++;notes.push('Training Ground unlocked');continue}
    if(a==='openPYQ'){setView('pyq');applied++;notes.push('PYQ Explorer opened');continue}
    if(a==='openStudyTimer'){setView('study');applied++;notes.push('Study Timer opened');continue}
    if(a==='openOMR'){setView('attempt');applied++;notes.push('OMR / Evaluation opened');continue}
    if(a==='saveStudyGoal'){const mins=Math.max(1,Math.round(Number(value)||0));const st=studyState();st.goals.daily=mins*60;saveStudyState(st);applied++;notes.push('Daily goal set to '+mins+' min');continue}
    if(a==='resetUI'){const before=JSON.parse(JSON.stringify(state.ui));state.ui={};saveUI();recordVersion('AI reset UI',before,state.ui);applied++;continue}
  }
  return {applied,notes:notes.join(' • ')};
}
function gLocalCommand(prompt){
  const p=prompt.toLowerCase().trim();
  const hasNavIntent=/^(open|go to|navigate to|show|view|take me to)\b/.test(p);
  const nav=hasNavIntent?Object.keys(gNavMap()).sort((a,b)=>b.length-a.length).find(k=>p.includes(k)):null;if(nav){const v=gNavigate(nav);return v?{reply:'Opened '+v+'.',actions:[]}:null}
  if(p.includes('training')&&('unlock'===p.split(/\s+/)[0]||p.includes('unlock'))){setView('training');saveGPrefs({trainingUnlocked:true});return {reply:'Training Ground is unlocked and open.',actions:[]}}
  if(p.includes('hide')&&p.includes('public')){const before=JSON.parse(JSON.stringify(state.ui));state.ui.hideSignals=true;saveUI();recordVersion('Local hide public signals',before,state.ui);render();return {reply:'Public signal cards hidden.',actions:[]}}
  if(p.includes('show')&&p.includes('public')){const before=JSON.parse(JSON.stringify(state.ui));state.ui.hideSignals=false;saveUI();recordVersion('Local show public signals',before,state.ui);render();return {reply:'Public signal cards shown.',actions:[]}}
  const rn=p.match(/(?:rename|name) (?:the dashboard|dashboard)?\s*(?:to|as)\s+(.+)$/i);if(rn){applyUIWithVersion('Local rename',ui=>{ui.title=rn[1].trim().slice(0,120)});return {reply:'Dashboard title updated.',actions:[]}}
  const note=p.match(/(?:add|set) (?:a )?note\s*[:\-]?\s*(.+)$/i);if(note){applyUIWithVersion('Local note',ui=>{ui.note=note[1].trim().slice(0,1000)});return {reply:'Dashboard note saved.',actions:[]}}
  if(p.includes('reset ui')){const before=JSON.parse(JSON.stringify(state.ui));state.ui={};saveUI();recordVersion('Local reset UI',before,state.ui);render();return {reply:'UI edits reset; history retained.',actions:[]}}
  if(p.includes('clear')&&p.includes('pyq')&&p.includes('filter')){state.filters={year:'ALL',subject:'ALL',theme:'ALL',topic:'ALL',format:'ALL',status:'ALL',ca:'ALL',neg:'ALL',news:'ALL',q:''};setView('pyq');return {reply:'PYQ filters cleared.',actions:[]}}
  if(p.includes('study tracker')||p.includes('study timer')||p.includes('open study')||p.includes('start studying')){setView('study');return {reply:'Study Timer opened.',actions:[]}}
  if(p.includes('omr')||p.includes('evaluation center')){setView('attempt');return {reply:'OMR & Evaluation Center opened.',actions:[]}}
  return null;
}
function gModuleCard(m){
  if(m.kind==='metric')return `<div class="g-module metric"><div class="label">${esc(m.title)}</div><div class="value cyan">${esc(m.content)}</div><div class="delta">AI runtime module</div></div>`;
  if(m.kind==='link')return `<div class="g-module"><div class="split"><strong>${esc(m.title)}</strong>${badge('LINK')}</div><a class="link linkbtn" href="${esc(m.url||'#')}" target="_blank" rel="noopener">${esc(m.content||'Open')} ↗</a></div>`;
  if(m.kind==='checklist')return `<div class="g-module"><div class="split"><strong>${esc(m.title)}</strong>${badge('CHECKLIST')}</div>${String(m.content||'').split(/\n|;/).filter(Boolean).map(x=>`<label class="checkline"><input type="checkbox"> <span>${esc(x)}</span></label>`).join('')}</div>`;
  if(m.kind==='countdown')return `<div class="g-module"><div class="split"><strong>${esc(m.title)}</strong>${badge('LIVE')}</div><div class="g-count" data-date="${esc(m.date||m.content)}">--</div><div class="small muted">Live local countdown</div></div>`;
  return `<div class="g-module"><div class="split"><strong>${esc(m.title)}</strong>${badge('AI NOTE')}</div><div class="g-copy">${esc(m.content||'')}</div></div>`;
}
function gCountdownHTML(event){return `<div class="count-card"><div class="split"><div><div class="eyebrow">LIVE COUNTDOWN</div><h3>${esc(event.name)}</h3></div>${badge(event.status)}</div><div class="count-number" data-event="${esc(event.id)}">--</div><div class="count-date">${new Date(event.date).toLocaleDateString('en-IN',{day:'2-digit',month:'long',year:'numeric',timeZone:'Asia/Kolkata'})}</div></div>`}
function gUpdateLiveClock(){
  const now=new Date();document.querySelectorAll('[data-live-clock]').forEach(el=>{el.textContent=now.toLocaleString('en-IN',{weekday:'short',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Kolkata'})+' IST'});
  const cfg=gConfig();for(const e of cfg.events){const el=document.querySelector(`[data-event="${CSS.escape(e.id)}"]`);if(!el)continue;const d=new Date(e.date).getTime();let ms=d-now.getTime();if(ms<=0){el.textContent='00d 00h 00m 00s';continue}const s=Math.floor(ms/1000),days=Math.floor(s/86400),hrs=Math.floor(s%86400/3600),mins=Math.floor(s%3600/60),secs=s%60;el.textContent=`${String(days).padStart(2,'0')}d ${String(hrs).padStart(2,'0')}h ${String(mins).padStart(2,'0')}m ${String(secs).padStart(2,'0')}s`}
  document.querySelectorAll('.g-count[data-date]').forEach(el=>{const d=new Date(el.dataset.date).getTime(),ms=d-now.getTime();if(Number.isFinite(d)&&ms>0){const s=Math.floor(ms/1000),dd=Math.floor(s/86400),hh=Math.floor(s%86400/3600),mm=Math.floor(s%3600/60),ss=s%60;el.textContent=`${String(dd).padStart(2,'0')}d ${String(hh).padStart(2,'0')}h ${String(mm).padStart(2,'0')}m ${String(ss).padStart(2,'0')}s`}else if(Number.isFinite(d))el.textContent='00d 00h 00m 00s'})
}
function gRenderHistory(){const rows=gHistory().slice(0,12);return rows.length?rows.map(x=>`<div class="history-row"><div><b>${esc(x.mode||'AI')}</b> <span class="muted">${esc(new Date(x.at||Date.now()).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</span></div><div>${esc(x.prompt||'')}</div><small>${esc(x.reply||'')}</small></div>`).join(''):'<div class="empty">No AI commands yet.</div>'}
function viewOverviewG(){const cfg=gConfig(),a=activityState(),d=study14(),today=d.at(-1)?.mins||0,week=d.slice(-7).reduce((n,x)=>n+x.mins,0),ss=studyState(),streak=calcStudyStreak(),active=ss.active;return `<div class="study-dashboard"><div class="study-hero"><div><div class="eyebrow">PERSONAL STUDY OS / UPSC PREPARATION</div><div class="hero-greeting">${greeting()}</div><div class="hero-sub">A recoverable StudyTracker-style dashboard for GS, CSAT, Philosophy Optional, mocks, PYQs, OMR and AI.</div><div class="hero-actions"><button class="btn primary" data-goto="study">▶ Start Studying</button><button class="btn" data-goto="training">Mock Test</button><button class="btn" data-goto="attempt">OMR Evaluation</button><button class="btn" data-goto="ai">AI Tutor</button></div></div><div class="hero-health"><div class="small muted">STUDY HEALTH</div><div class="hero-score">${Math.min(100,Math.round(week/600*100))}</div><div class="small">recent activity index</div></div></div><div class="dashboard-stat-row"><div class="stat-pill">⚡ Level 1</div><div class="stat-pill">🔥 ${streak}d streak</div><div class="stat-pill">⏱ ${today}m today</div><div class="stat-pill">🏆 ${ss.sessions.length} sessions</div>${active?`<div class="stat-pill study-live-pill">⏳ ${esc(active.subject)} • ${fmtTime(studyElapsedSec(active))}</div>`:''}</div><div class="grid g4" style="margin-top:14px">${metric('TODAY',today+' min','study time','cyan')}${metric('THIS WEEK',week+' min','7-day total','purple')}${metric('STREAK',streak+' days','consecutive days','amber')}${metric('SESSIONS',ss.sessions.length,'auto-saved','green')}</div><div class="grid g2" style="margin-top:14px"><div class="card dashboard-chart"><div class="split"><h3 class="section-title">14-Day Activity</h3>${badge('2D • LIVE')}</div>${studyGraph2D()}</div><div class="card"><div class="split"><h3 class="section-title">Exam Countdown</h3>${badge('IST')}</div><div class="count-mini-grid">${cfg.events.map(e=>`<div class="count-card compact event-${esc(e.id)}"><div class="small muted">${esc(e.name)}</div><div class="count-number ${e.id==='upsc'?'count-upsc':'count-uppsc'}" data-event="${esc(e.id)}">--</div><div class="count-date">${new Date(e.date).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Kolkata'})}</div></div>`).join('')}</div><div class="notice" style="margin-top:10px">UPSC countdown stays global on the dashboard; UPPSC is dashboard-only.</div></div></div><div class="grid g4" style="margin-top:14px"><button class="feature-tile" data-goto="pyq"><b>◫ PYQ Explorer</b><small>2014–2026 • full local text where available</small></button><button class="feature-tile" data-goto="study"><b>◷ Focus Timer</b><small>23 separate subject clocks</small></button><button class="feature-tile" data-goto="studyCommand"><b>◆ Study Intelligence</b><small>Tracker + schedule + AI command layer</small></button><button class="feature-tile" data-goto="attempt"><b>↯ OMR</b><small>Review → Key Vault → Result</small></button></div><div class="grid g2" style="margin-top:14px"><div class="card"><div class="split"><h3 class="section-title">Quick Access</h3>${badge('A → Z')}</div><div class="quick-grid"><button class="command-chip" data-goto="training">Focus / Mock</button><button class="command-chip" data-goto="study">Study Tracker</button><button class="command-chip" data-goto="pyq">PYQ</button><button class="command-chip" data-goto="attempt">OMR</button><button class="command-chip" data-goto="result">Results</button><button class="command-chip" data-goto="ai">AI Tutor</button><button class="command-chip" data-goto="reports">Reports</button><button class="command-chip" data-goto="vault">Data Vault</button></div></div><div class="card"><div class="split"><h3 class="section-title">Recent Activity</h3>${badge(String(a.events.length))}</div><div class="activity-list">${a.events.slice(0,10).map(x=>`<div class="activity-row"><b>${esc(x.type)}</b><span>${esc(new Date(x.at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}))}</span><small>${esc(JSON.stringify(x.meta||{}))}</small></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div></div></div><div class="card" style="margin-top:14px"><div class="split"><h3 class="section-title">Subject Colour Coding</h3>${badge('NO COLOUR MIXING')}</div>${subjectLegend()}</div></div>`}

function viewAIG(){const hist=gHistory(),last=hist[0],initial=last?`${esc(last.reply||'')}`:'Run a command or ask a research question.',preview=AI_CAPABILITIES.slice(0,30).map((x,i)=>`<span class="ai-cap" title="${esc(x)}">${String(i+1).padStart(3,'0')} ${esc(x)}</span>`).join('');return `<div class="view-head"><div><div class="eyebrow">AI / OPERATOR + RESEARCH</div><div class="title">PRECISION AI Command Center</div><div class="desc">Gemini 3.8 Flash operator with local portal context, optional Google Search grounding, safe UI actions, persistent research history and recovery-aware execution.</div></div>${badge(state.aiBusy?'RUNNING':'READY')}</div><div class="grid g2"><div class="card"><div class="split"><h3 class="section-title">Ask / Command</h3>${badge(AI_CAPABILITIES.length+' CAPABILITIES')}</div><textarea id="aiPrompt" class="ai-input ai-prompt-large" placeholder="Example: Analyse 2024–2026 Economy PYQs, show the recurring themes, open Trend Analytics, and keep the answer in evidence labels."></textarea><div class="toolbar-row"><label><input type="checkbox" id="aiWeb" ${gPrefs().aiWebGrounding!==false?'checked':''}> Live web grounding</label><label><input type="checkbox" id="aiApply" ${gPrefs().aiAutoApply!==false?'checked':''}> Apply safe UI actions</label><label><input type="checkbox" id="aiDeep"> Deep local retrieval</label></div><div class="actions" style="margin-top:10px"><button class="btn primary" id="runAI_G">Run AI</button><button class="btn" id="clearAI_G">Clear</button></div><div id="aiStatus" class="notice" style="margin-top:10px">Ready. Browser-side Gemini key is configured for this personal portal.</div></div><div class="card"><div class="split"><h3 class="section-title">Gemini connection</h3>${badge(gKey()?'KEY CONFIGURED':'KEY REQUIRED')}</div><label class="small muted">API base</label><input id="aiBase_G" class="ai-input single" value="${esc(gBase())}"><label class="small muted">Model</label><input id="aiModel_G" class="ai-input single" value="${esc(gModel())}"><label class="small muted">Gemini API key</label><input id="aiKey_G" type="text" autocomplete="off" class="ai-input single" value="${esc(gKey())}"><div class="actions" style="margin-top:8px"><button class="btn primary" id="saveAI_G">Save settings</button><button class="btn" id="testAI_G">Test connection</button></div><div class="notice" style="margin-top:10px"><strong>Important:</strong> because this is a static Vercel site, a browser-side key is visible to the browser. The panel includes a live connection test and does not pretend the key is server-side.</div></div></div><div class="card ai-response-card" style="margin-top:14px"><div class="split"><h3 class="section-title">Live response</h3><div id="aiLiveMeta">Database context: ON • History: ${hist.length}</div></div><div id="aiStream" class="ai-stream">${initial}</div><div id="aiSources" class="source-chips"></div></div><div class="grid g2" style="margin-top:14px"><div class="card"><div class="split"><h3 class="section-title">AI Capability Matrix</h3>${badge('A → Z')}</div><div class="ai-cap-grid">${preview}</div></div><div class="card"><div class="split"><h3 class="section-title">AI history</h3>${badge(String(hist.length))}</div><div class="history-list">${gRenderHistory()}</div></div></div>`}

