  $('#exportStudy')?.addEventListener('click',()=>exportBlob('precision-study-tracker-backup.json',JSON.stringify({activity:activityState(),study:studyState()},null,2),'application/json'));$('#exportSubjectCSV')?.addEventListener('click',()=>{const st=studyState();const rows=[['subject','group','seconds','minutes'],...STUDY_SUBJECTS.map(m=>[m.label,m.group,Number(st.subjects[m.label]||0),(Number(st.subjects[m.label]||0)/60).toFixed(2)])];exportBlob('precision-study-subject-ledger.csv',rows.map(r=>r.map(x=>'\"'+String(x).replaceAll('\"','\"\"')+'\"').join(',')).join('\n'),'text/csv')});
  $('#clearStudy')?.addEventListener('click',()=>{if(confirm('Clear local study history?')){saveActivity({days:{},events:[],current:{startedAt:Date.now(),lastAt:Date.now()},version:1});const st=studyState();st.sessions=[];st.subjects={};st.active=null;saveStudyState(st);render()}});
  $('#undoUI_G')?.addEventListener('click',()=>{const hist=gVersions();const last=hist[0];if(!last){alert('No version history.');return}state.ui=JSON.parse(JSON.stringify(last.before));saveUI();saveVersions(hist.slice(1));applyUI();render()});
  $('#clearHistory_G')?.addEventListener('click',()=>{saveVersions([]);render()});
