async function runAIG(){
  const input=$('#aiPrompt');if(!input)return;const prompt=input.value.trim();if(!prompt)return;const live=$('#aiStream'),sourcesEl=$('#aiSources');
  const web=$('#aiWeb')?.checked ?? gPrefs().aiWebGrounding!==false,apply=$('#aiApply')?.checked ?? gPrefs().aiAutoApply!==false,deep=$('#aiDeep')?.checked ?? false;
  if(!live)return;if(sourcesEl)sourcesEl.innerHTML='';
  try{
    const local=gLocalCommand(prompt);
    if(local){const applied=apply?gRunActions(local):{applied:0,notes:''};state.aiBusy=false;const target=$('#aiStream');if(target)target.textContent=local.reply+(applied.notes?' • '+applied.notes:'');pushAIHistory({at:new Date().toISOString(),mode:'LOCAL',prompt,reply:local.reply});render();return}
    state.aiBusy=true;live.textContent='Thinking with local database context…';render();
    if(!gKey()){throw new Error('No Gemini API key saved in this browser. Open Admin / AI settings and paste your key once.')}
    const commandish=/\b(open|go to|navigate|show|hide|rename|add|create|enable|disable|unlock|reset|remove|set)\b/i.test(prompt) && !/\b(analyse|analyze|research|compare|why|explain|summarize|pattern|trend)\b/i.test(prompt);
    if(commandish){
      showAIStatus('Gemini command agent is running…');
      const r=await geminiGenerate(prompt,{command:true,web:false,deep});
      const obj=gParseJSON(r.text)||{};const applied=apply?gRunActions(obj):{applied:0,notes:''};const reply=obj.reply||r.text||'Command processed.';live.textContent=reply+(applied.notes?'\n\nApplied: '+applied.notes:'');pushAIHistory({at:new Date().toISOString(),mode:'COMMAND',prompt,reply});
    }else{
      showAIStatus('Gemini analyst is streaming…');
      const r=await geminiStream(prompt,{web,deep,onText:t=>{const el=$('#aiStream');if(el){el.textContent=t;el.scrollTop=el.scrollHeight}}});
      live.textContent=r.text||'No text response.';pushAIHistory({at:new Date().toISOString(),mode:'ANALYST',prompt,reply:r.text});
      if(sourcesEl&&r.sources?.length)sourcesEl.innerHTML=r.sources.map(s=>`<a class="source-chip" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('');
      if(sourcesEl&&r.queries?.length)sourcesEl.insertAdjacentHTML('afterbegin',`<div class="small muted">Web queries: ${esc(r.queries.join(' • '))}</div>`);
    }
    showAIStatus('Completed.','info');
  }catch(e){live.textContent='AI error: '+e.message;showAIStatus(e.message,'error')}
  finally{state.aiBusy=false;render();}
}

