function updateGlobalTimer(){const el=$('#globalTimer');if(!el)return;const e=engineState(),r=e.run;const st=studyState();if(r&&['COUNTDOWN','RUNNING','PAUSED','SUBMIT_READY'].includes(r.state)){let text=r.state==='COUNTDOWN'?fmtTime(r.countdownRemaining):fmtTime(Math.max(0,7200-(r.elapsed||0)));if(r.state==='PAUSED')text+=' • PAUSED';if(r.state==='SUBMIT_READY')text+=' • SUBMIT';el.textContent='TEST • '+text;el.classList.add('timer-live');return}if(st.active){el.textContent='STUDY • '+fmtTime(studyElapsedSec(st.active))+' • '+st.active.subject+(st.active.pausedAt?' • PAUSED':'');el.classList.add('timer-live');return}el.textContent='NO ACTIVE TIMER';el.classList.remove('timer-live')}
function study14(){
  try{
    const s=studyState(),out=[];
    for(let i=13;i>=0;i--){
      const d=new Date(); d.setDate(d.getDate()-i);
      const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});
      const dayStart=new Date(key+'T00:00:00+05:30').getTime(), dayEnd=dayStart+86400000;
      let sec=0;
      for(const row of (s.sessions||[])){
        const st=Number(row.startedAt||0), en=Number(row.endedAt||0);
        if(!st||!en) continue;
        sec += Math.max(0, Math.min(en,dayEnd)-Math.max(st,dayStart))/1000;
      }
      if(i===0 && s.active){
        const now=Date.now(), st=Number(s.active.startedAt||now);
        const pausedMs=Number(s.active.pausedMs||0);
        const currentPause=s.active.pausedAt?Math.max(0,now-Number(s.active.pausedAt)):0;
        const effectiveEnd=Math.max(st,now-currentPause);
        sec += Math.max(0, Math.min(effectiveEnd,dayEnd)-Math.max(st,dayStart)-pausedMs)/1000;
      }
      out.push({key,label:d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',timeZone:'Asia/Kolkata'}),mins:Math.floor(sec/60)});
    }
    return out;
  }catch(e){
    const a=activityState(),out=[];
    for(let i=13;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});out.push({key,label:d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',timeZone:'Asia/Kolkata'}),mins:Math.round((Number(a.days[key])||0)/60)});}
    return out;
  }
}
function studyGraph2D(){const pts=study14(),max=Math.max(1,...pts.map(x=>x.mins)),w=900,h=250,pad=36;const xs=pts.map((_,i)=>pad+i*(w-pad*2)/13);const ys=pts.map(x=>h-pad-(x.mins/max)*(h-pad*2));const poly=pts.map((x,i)=>`${xs[i].toFixed(1)},${ys[i].toFixed(1)}`).join(' ');return `<svg class="study-graph-2d" viewBox="0 0 ${w} ${h}" role="img" aria-label="14-day study activity graph"><defs><linearGradient id="studyFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-opacity=".55"/><stop offset="100%" stop-opacity=".02"/></linearGradient></defs><path d="M ${xs[0]} ${h-pad} L ${poly.replaceAll(',', ' ')} L ${xs.at(-1)} ${h-pad} Z" fill="url(#studyFill)" opacity=".28"/><polyline points="${poly}" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="currentColor" opacity=".16"/><g>${pts.map((x,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="${x.mins?4:2.5}" fill="currentColor"/><text x="${xs[i]}" y="${h-10}" text-anchor="middle" font-size="11">${x.label}</text>`).join('')}</g></svg>`}
function studyState(){const d=loadLocalJSON('precision-study-state',{active:null,sessions:[],goals:{daily:600,subject:{}},subjects:{},mode:'focus',settings:{defaultTargetSec:0,sound:true,autoStop:true}});d.sessions ||= [];d.subjects ||= {};d.goals ||= {daily:600,subject:{}};d.goals.subject ||= {};d.mode ||= 'focus';d.settings ||= {defaultTargetSec:0,sound:true,autoStop:true};return d}
function saveStudyState(v){saveLocalJSON('precision-study-state',v)}
function studyElapsedSec(a,at=Date.now()){if(!a)return 0;const paused=(a.pausedMs||0)+(a.pausedAt?Math.max(0,at-a.pausedAt):0);return Math.max(0,Math.floor((at-a.startedAt-paused)/1000))}
function studyTargetRemaining(a,at=Date.now()){if(!a||!a.targetSec)return 0;return Math.max(0,a.targetSec-studyElapsedSec(a,at))}
function startStudySession(subject='Indian Polity',notes='',targetSec=null){const s=studyState();if(s.active)return false;const meta=subjectMeta(subject);const target=Number.isFinite(Number(targetSec))?Math.max(0,Number(targetSec)):Math.max(0,Number(s.settings.defaultTargetSec||0));s.active={id:'S-'+Date.now(),subject:meta.label,subjectId:meta.id,notes,startedAt:Date.now(),pausedMs:0,lastAutosave:Date.now(),targetSec:target};saveStudyState(s);logActivity('study-session-start',{subject:meta.label,subjectId:meta.id,targetSec:target});return true}
function pauseStudySession(reason='manual'){const s=studyState();if(!s.active||s.active.pausedAt)return;s.active.pausedAt=Date.now();s.active.lastAutosave=Date.now();s.active.pauseReason=reason;saveStudyState(s);logActivity('study-session-pause',{subject:s.active.subject,reason})}
function resumeStudySession(){const s=studyState();if(!s.active?.pausedAt)return;s.active.pausedMs=(s.active.pausedMs||0)+(Date.now()-s.active.pausedAt);delete s.active.pausedAt;delete s.active.pauseReason;s.active.lastAutosave=Date.now();saveStudyState(s);logActivity('study-session-resume',{subject:s.active.subject})}
function stopStudySession(){const s=studyState(),a=s.active;if(!a)return;const end=Date.now(),duration=studyElapsedSec(a,end);const row={id:a.id,subject:a.subject,subjectId:a.subjectId||subjectMeta(a.subject).id,notes:a.notes,startedAt:a.startedAt,endedAt:end,durationSec:duration,targetSec:Number(a.targetSec||0),completedTarget:!!a.targetSec&&duration>=a.targetSec};s.sessions.unshift(row);s.sessions=s.sessions.slice(0,2000);s.subjects[a.subject]=(s.subjects[a.subject]||0)+duration;s.active=null;saveStudyState(s);logActivity('study-session-end',{subject:a.subject,durationSec:duration,completedTarget:row.completedTarget});if(row.completedTarget&&s.settings.sound)studyBeep();return row}
function studyBeep(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=880;g.gain.value=.08;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.18);o.onended=()=>c.close?.()}catch{}}
function autosaveStudyTick(){const s=studyState();if(!s.active||s.active.pausedAt)return;const now=Date.now(),sec=studyElapsedSec(s.active);if((now-(s.active.lastAutosave||0))>=3000){s.active.lastAutosave=now;saveStudyState(s);const a=activityState(),delta=Math.max(0,(now-(a.current?.lastAt||now))/1000);if(delta>0&&delta<30){const d=todayKey();a.days[d]=(Number(a.days[d])||0)+delta;a.current={...(a.current||{}),lastAt:now};saveActivity(a);}if(s.active.targetSec&&sec>=s.active.targetSec){if(s.settings.autoStop!==false)stopStudySession();else{s.active.targetReachedAt=s.active.targetReachedAt||now;saveStudyState(s);if(s.settings.sound)studyBeep();}}}}
function calcStudyStreak(){const a=studyState(),keys=new Set(a.sessions.filter(x=>x?.endedAt&&x.durationSec>0).map(x=>new Date(x.endedAt).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})));let n=0,d=new Date();while(n<365){const k=d.toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});if(!keys.has(k))break;n++;d.setDate(d.getDate()-1)}return n}
function subjectStudyRows(){const s=studyState();return STUDY_SUBJECTS.map(meta=>({meta,sec:Number(s.subjects[meta.label]||0)})).filter(x=>x.sec>0).sort((a,b)=>b.sec-a.sec)}
function renderSubjectOptions(active){return STUDY_SUBJECTS.map(x=>`<option value="${esc(x.label)}" ${active===x.label?'selected':''}>${esc(x.label)} • ${esc(x.group)}</option>`).join('')}
